const int M = 105;
int src[51], id[51][M];
pii roads[51];
int cnt, head[N], d[N], p[N], vis[N];
struct node{
    int v, c, w, next;
}g[N<<2];
void add_edge(int a, int b, int c, int w){
    g[cnt] = {b, c, w, head[a]}, head[a] = cnt++;
    g[cnt] = {a, 0, -w, head[b]}, head[b] = cnt++;
}
bool spfa(int s, int t){
    rep(i,0,t+1) d[i] = inf, vis[i] = 0;
    queue<int>q;
    q.push(s); d[s] = 0;
    while(!q.empty()){
        int u = q.front(); q.pop(); vis[u] = 0;
        for(int i = head[u]; ~i; i = g[i].next){
            int j = g[i].v;
            if(g[i].c && d[j] > d[u] + g[i].w){
                d[j] = d[u] + g[i].w;
                p[j] = i;
                if(!vis[j]){
                    vis[j] = 1;
                    q.push(j);
                }
            }
        }
    }
    return d[t] < inf;
}
int max_flow(int s, int t){
    int ans = 0, res = 0;
    while(spfa(s, t)){
        int x = t, f = inf;
        while(x != s){
            Min(f, g[p[x]].c), x = g[p[x] ^ 1].v;
        }
        ans += f * d[t];
        res += f;
        x = t;
        while(x != s){
            g[p[x]].c -= f, g[p[x] ^ 1].c += f;
            x = g[p[x] ^ 1].v;
        }
    }
    DBG(res)
    return ans;
}
