            int cost_mult = D;
            rep(k,0,K){
                add_edge(id[x][j], id[y][j+1], 1, cost_mult * (2*k + 1));
                add_edge(id[y][j], id[x][j+1], 1, cost_mult * (2*k + 1));
            }
        }
    }
    int ans = max_flow(s, t);
    printf("%d\n", ans);
}
